{
  "claims": [
    {
      "claim": "1-Acetamidopyrene, which shares the acetamido-pyrene core with the query, is positive in TDC training labels and in Ames tests using TA98, TA98NR and TA98/1,8-DNP6, both with and without S9. This strongly supports a positive outcome for the query because the acetamido-pyrene moiety is the key mutagenic liability, and the additional quinone carbonyls add redox/DNA-reactive potential.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 1", "Molecule 11"],
      "record_ids": ["Record 1-1", "Record 11-1", "Record 11-2", "Record 11-4"]
    },
    {
      "claim": "Hydroxylated acetamidopyrenes such as 1-acetamidopyren-8-ol, -6-ol and -3-ol are positive in TDC labels and/or Ames TA98 assays, with activity dependent on N-oxidation and O-acetylation. These pathways are available to the query's acetamido group and support a positive bacterial reverse-mutation prediction.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 2", "Molecule 4", "Molecule 5", "Molecule 12", "Molecule 14", "Molecule 19"],
      "record_ids": ["Record 2-1", "Record 12-1", "Record 12-2", "Record 14-2", "Record 14-4", "Record 19-1"]
    },
    {
      "claim": "Acetamido-substituted polycyclic quinone/ketone systems, including diacetamidoanthraquinone and 3-acetylaminobenzanthrone, are positive in Salmonella reversion assays. This provides direct support for an acetamido group combined with a quinone/ketone-containing polycyclic scaffold being mutagenic.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 9", "Molecule 34"],
      "record_ids": ["Record 9-1", "Record 34-1"]
    },
    {
      "claim": "N-hydroxy-N-acetyl-1-aminopyrene and N-hydroxy-1-aminopyrene are positive in Salmonella, supporting the bioactivation pathway of acetamido-pyrenes to reactive nitrenium species that cause bacterial reverse mutations.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 20", "Molecule 21"],
      "record_ids": ["Record 20-1", "Record 21-1"]
    },
    {
      "claim": "Quinone-only evidence is mixed: an unsubstituted pyrenequinone was negative in E. coli WP2, and some B[a]P-quinones show low ROS-mediated Ames activity, but 9,10-pyrenequinone and B[a]P-7,8-dione are positive in Salmonella. These quinone data do not outweigh the strong positive acetamido-pyrene evidence, but they provide limited contradictory context.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 16", "Molecule 18", "Molecule 27"],
      "record_ids": ["Record 16-1", "Record 16-2", "Record 18-1", "Record 27-1"]
    }
  ],
